"""Predicate analysis with lightweight linear constraint reasoning."""

from __future__ import annotations

import ast
from dataclasses import dataclass
from fractions import Fraction
import re
from typing import Iterable

from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import is_nondeterministic
from cpachecker.result import VerificationResult
from cpachecker.analyses.value_analysis import (
    CompositeCPA,
    DomainStopOperator,
    LocationCPA,
    SeparateMergeOperator,
    TrivialPrecision,
    run_cpa_algorithm,
)


INTEGER_SUFFIX_RE = re.compile(r"\b(\d+)[UuLl]+\b")


def _sanitize_c_expression(expression: str) -> str:
    cleaned = INTEGER_SUFFIX_RE.sub(r"\1", expression.strip())
    cleaned = cleaned.replace("&&", " and ").replace("||", " or ")
    cleaned = re.sub(r"(?<![!<>=])!(?!=)", " not ", cleaned)
    return cleaned


@dataclass(frozen=True)
class LinearExpr:
    coeffs: tuple[tuple[str, int], ...] = ()
    const: int = 0

    @staticmethod
    def constant(value: int) -> "LinearExpr":
        return LinearExpr((), int(value))

    @staticmethod
    def variable(name: str) -> "LinearExpr":
        return LinearExpr(((name, 1),), 0)

    def normalize(self) -> "LinearExpr":
        merged: dict[str, int] = {}
        for variable, coeff in self.coeffs:
            merged[variable] = merged.get(variable, 0) + coeff
        normalized = tuple(sorted((var, coeff) for var, coeff in merged.items() if coeff))
        return LinearExpr(normalized, self.const)

    def __add__(self, other: "LinearExpr") -> "LinearExpr":
        return LinearExpr(self.coeffs + other.coeffs, self.const + other.const).normalize()

    def __sub__(self, other: "LinearExpr") -> "LinearExpr":
        return self + other.scale(-1)

    def scale(self, factor: int) -> "LinearExpr":
        return LinearExpr(
            tuple((variable, coeff * factor) for variable, coeff in self.coeffs),
            self.const * factor,
        ).normalize()

    def variables(self) -> tuple[str, ...]:
        return tuple(variable for variable, _ in self.coeffs)

    def contains(self, variable: str) -> bool:
        return any(name == variable for name, _ in self.coeffs)

    def coefficient(self, variable: str) -> int:
        for name, coeff in self.coeffs:
            if name == variable:
                return coeff
        return 0

    def without_variable(self, variable: str) -> "LinearExpr":
        return LinearExpr(
            tuple((name, coeff) for name, coeff in self.coeffs if name != variable),
            self.const,
        ).normalize()

    def substitute(self, variable: str, replacement: "LinearExpr") -> "LinearExpr":
        coeff = self.coefficient(variable)
        if coeff == 0:
            return self
        base = self.without_variable(variable)
        return base + replacement.scale(coeff)

    def evaluate_constant(self) -> int | None:
        if self.coeffs:
            return None
        return self.const

    def solve_for_single_variable(self) -> tuple[str, "LinearExpr"] | None:
        for variable, coeff in self.coeffs:
            if coeff not in (1, -1):
                continue
            remainder = self.without_variable(variable)
            if coeff == 1:
                replacement = remainder.scale(-1)
            else:
                replacement = remainder
            return variable, replacement
        return None

    def __repr__(self) -> str:
        parts: list[str] = []
        for variable, coeff in self.coeffs:
            if coeff == 1:
                parts.append(variable)
            elif coeff == -1:
                parts.append(f"-{variable}")
            else:
                parts.append(f"{coeff}*{variable}")
        if self.const or not parts:
            parts.append(str(self.const))
        return " + ".join(parts).replace("+ -", "- ")


@dataclass(frozen=True)
class LinearConstraint:
    expr: LinearExpr
    operator: str

    def normalize(self) -> "LinearConstraint":
        return LinearConstraint(self.expr.normalize(), self.operator)

    def substitute(self, variable: str, replacement: LinearExpr) -> "LinearConstraint":
        return LinearConstraint(self.expr.substitute(variable, replacement), self.operator)

    def contains(self, variable: str) -> bool:
        return self.expr.contains(variable)

    def negate(self) -> "LinearConstraint":
        negated = {
            "==": "!=",
            "!=": "==",
            "<": ">=",
            "<=": ">",
            ">": "<=",
            ">=": "<",
        }
        return LinearConstraint(self.expr, negated[self.operator])

    def constant_truth_value(self) -> bool | None:
        value = self.expr.evaluate_constant()
        if value is None:
            return None
        if self.operator == "==":
            return value == 0
        if self.operator == "!=":
            return value != 0
        if self.operator == "<":
            return value < 0
        if self.operator == "<=":
            return value <= 0
        if self.operator == ">":
            return value > 0
        if self.operator == ">=":
            return value >= 0
        raise ValueError(f"Unsupported operator: {self.operator}")

    def canonical_key(self) -> tuple[tuple[tuple[str, int], ...], str, int]:
        return (self.expr.coeffs, self.operator, self.expr.const)

    def __repr__(self) -> str:
        return f"{self.expr!r} {self.operator} 0"


def parse_linear_expression(expression: str) -> LinearExpr | None:
    """Parse a linear arithmetic expression over program variables."""

    cleaned = _sanitize_c_expression(expression)
    try:
        tree = ast.parse(cleaned, mode="eval")
    except SyntaxError:
        return None
    return _parse_linear_node(tree.body)


def _parse_linear_node(node: ast.AST) -> LinearExpr | None:
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, bool)):
        return LinearExpr.constant(int(node.value))

    if isinstance(node, ast.Name):
        return LinearExpr.variable(node.id)

    if isinstance(node, ast.UnaryOp):
        operand = _parse_linear_node(node.operand)
        if operand is None:
            return None
        if isinstance(node.op, ast.USub):
            return operand.scale(-1)
        if isinstance(node.op, ast.UAdd):
            return operand
        return None

    if isinstance(node, ast.BinOp):
        left = _parse_linear_node(node.left)
        right = _parse_linear_node(node.right)
        if left is None or right is None:
            return None
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            left_const = left.evaluate_constant()
            right_const = right.evaluate_constant()
            if left_const is not None:
                return right.scale(left_const)
            if right_const is not None:
                return left.scale(right_const)
            return None
        return None

    return None


def parse_condition_constraints(expression: str, truth_value: bool) -> list[LinearConstraint] | None:
    cleaned = _sanitize_c_expression(expression)
    try:
        tree = ast.parse(cleaned, mode="eval")
    except SyntaxError:
        return None
    return _parse_condition_node(tree.body, negate=not truth_value)


def _parse_condition_node(
    node: ast.AST, negate: bool = False
) -> list[LinearConstraint] | None:
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return _parse_condition_node(node.operand, negate=not negate)

    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And) and not negate:
            constraints: list[LinearConstraint] = []
            for value in node.values:
                parsed = _parse_condition_node(value, negate=False)
                if parsed is None:
                    return None
                constraints.extend(parsed)
            return constraints
        return None

    if isinstance(node, ast.Compare):
        left = _parse_linear_node(node.left)
        if left is None:
            return None
        constraints: list[LinearConstraint] = []
        current_left = left
        for operator_node, comparator in zip(node.ops, node.comparators):
            right = _parse_linear_node(comparator)
            if right is None:
                return None
            operator = _comparison_operator(operator_node)
            constraint = LinearConstraint(current_left - right, operator)
            constraints.append(constraint.negate() if negate else constraint)
            current_left = right
        return constraints

    expr = _parse_linear_node(node)
    if expr is None:
        return None
    constraint = LinearConstraint(expr, "==" if negate else "!=")
    return [constraint]


def _comparison_operator(operator_node: ast.AST) -> str:
    if isinstance(operator_node, ast.Eq):
        return "=="
    if isinstance(operator_node, ast.NotEq):
        return "!="
    if isinstance(operator_node, ast.Lt):
        return "<"
    if isinstance(operator_node, ast.LtE):
        return "<="
    if isinstance(operator_node, ast.Gt):
        return ">"
    if isinstance(operator_node, ast.GtE):
        return ">="
    raise ValueError(f"Unsupported comparison operator: {operator_node!r}")


@dataclass
class _Bounds:
    lower: tuple[Fraction, bool] | None = None
    upper: tuple[Fraction, bool] | None = None
    exact: Fraction | None = None
    forbidden: set[Fraction] | None = None

    def __post_init__(self) -> None:
        if self.forbidden is None:
            self.forbidden = set()


class PathFeasibilityChecker:
    """Checks satisfiability of linear constraints by substitution and bounds."""

    def is_satisfiable(self, predicates: Iterable[LinearConstraint]) -> bool:
        reduced = self._reduce_constraints(predicates)
        if reduced is None:
            return False
        return self._check_bounds(reduced)

    def implies(
        self, premises: Iterable[LinearConstraint], conclusion: LinearConstraint
    ) -> bool:
        return not self.is_satisfiable([*premises, conclusion.negate()])

    def _reduce_constraints(
        self, predicates: Iterable[LinearConstraint]
    ) -> list[LinearConstraint] | None:
        constraints = [predicate.normalize() for predicate in predicates]
        substitutions: dict[str, LinearExpr] = {}

        changed = True
        while changed:
            changed = False
            for predicate in constraints:
                substituted = self._apply_substitutions(predicate, substitutions)
                if substituted.operator != "==":
                    continue
                solution = substituted.expr.solve_for_single_variable()
                if solution is None:
                    continue
                variable, replacement = solution
                if variable in substitutions:
                    continue
                replacement = self._substitute_expr(replacement, substitutions)
                substitutions[variable] = replacement
                substitutions = {
                    name: expr if name == variable else expr.substitute(variable, replacement)
                    for name, expr in substitutions.items()
                }
                changed = True
                break

        reduced: list[LinearConstraint] = []
        for predicate in constraints:
            substituted = self._apply_substitutions(predicate, substitutions)
            truth_value = substituted.constant_truth_value()
            if truth_value is True:
                continue
            if truth_value is False:
                return None
            if substituted not in reduced:
                reduced.append(substituted)
        return reduced

    def _apply_substitutions(
        self, predicate: LinearConstraint, substitutions: dict[str, LinearExpr]
    ) -> LinearConstraint:
        expr = self._substitute_expr(predicate.expr, substitutions)
        return LinearConstraint(expr.normalize(), predicate.operator)

    def _substitute_expr(
        self, expr: LinearExpr, substitutions: dict[str, LinearExpr]
    ) -> LinearExpr:
        updated = expr
        changed = True
        while changed:
            changed = False
            for variable, replacement in substitutions.items():
                if updated.contains(variable):
                    updated = updated.substitute(variable, replacement)
                    changed = True
        return updated.normalize()

    def _check_bounds(self, predicates: Iterable[LinearConstraint]) -> bool:
        bounds_by_form: dict[tuple[tuple[str, int], ...], _Bounds] = {}

        for predicate in predicates:
            expr, operator = self._canonicalize_sign(predicate.expr, predicate.operator)
            if not expr.coeffs:
                truth_value = LinearConstraint(expr, operator).constant_truth_value()
                if truth_value is False:
                    return False
                continue

            key = expr.coeffs
            bound = Fraction(-expr.const, 1)
            bounds = bounds_by_form.setdefault(key, _Bounds())

            if operator == "==":
                if bounds.exact is not None and bounds.exact != bound:
                    return False
                bounds.exact = bound
            elif operator == "!=":
                bounds.forbidden.add(bound)
            elif operator == ">":
                bounds.lower = self._max_lower(bounds.lower, (bound, True))
            elif operator == ">=":
                bounds.lower = self._max_lower(bounds.lower, (bound, False))
            elif operator == "<":
                bounds.upper = self._min_upper(bounds.upper, (bound, True))
            elif operator == "<=":
                bounds.upper = self._min_upper(bounds.upper, (bound, False))

        for bounds in bounds_by_form.values():
            if bounds.exact is not None:
                if bounds.exact in bounds.forbidden:
                    return False
                if bounds.lower and not self._satisfies_lower(bounds.exact, bounds.lower):
                    return False
                if bounds.upper and not self._satisfies_upper(bounds.exact, bounds.upper):
                    return False
                continue
            if bounds.lower and bounds.upper:
                lower_value, lower_strict = bounds.lower
                upper_value, upper_strict = bounds.upper
                if lower_value > upper_value:
                    return False
                if lower_value == upper_value and (lower_strict or upper_strict):
                    return False
        return True

    def _canonicalize_sign(
        self, expr: LinearExpr, operator: str
    ) -> tuple[LinearExpr, str]:
        if not expr.coeffs:
            return expr, operator
        if expr.coeffs[0][1] > 0:
            return expr, operator
        flipped = {
            "<": ">",
            "<=": ">=",
            ">": "<",
            ">=": "<=",
            "==": "==",
            "!=": "!=",
        }
        return expr.scale(-1), flipped[operator]

    def _max_lower(
        self,
        current: tuple[Fraction, bool] | None,
        candidate: tuple[Fraction, bool],
    ) -> tuple[Fraction, bool]:
        if current is None:
            return candidate
        if candidate[0] > current[0]:
            return candidate
        if candidate[0] < current[0]:
            return current
        return (current[0], current[1] or candidate[1])

    def _min_upper(
        self,
        current: tuple[Fraction, bool] | None,
        candidate: tuple[Fraction, bool],
    ) -> tuple[Fraction, bool]:
        if current is None:
            return candidate
        if candidate[0] < current[0]:
            return candidate
        if candidate[0] > current[0]:
            return current
        return (current[0], current[1] or candidate[1])

    def _satisfies_lower(
        self, value: Fraction, lower: tuple[Fraction, bool]
    ) -> bool:
        lower_value, strict = lower
        return value > lower_value if strict else value >= lower_value

    def _satisfies_upper(
        self, value: Fraction, upper: tuple[Fraction, bool]
    ) -> bool:
        upper_value, strict = upper
        return value < upper_value if strict else value <= upper_value


@dataclass(frozen=True)
class PredicateAbstractState(AbstractState):
    predicates: tuple[LinearConstraint, ...] = ()

    @classmethod
    def from_constraints(
        cls, predicates: Iterable[LinearConstraint]
    ) -> "PredicateAbstractState":
        normalized = []
        for predicate in predicates:
            simplified = predicate.normalize()
            truth_value = simplified.constant_truth_value()
            if truth_value is True:
                continue
            normalized.append(simplified)
        unique = tuple(sorted(set(normalized), key=lambda item: repr(item)))
        return cls(unique)

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, PredicateAbstractState)
            and self.predicates == other.predicates
        )

    def __hash__(self) -> int:
        return hash(self.predicates)

    def __repr__(self) -> str:
        return f"PredicateAbstractState({list(self.predicates)!r})"


class PredicateAbstractDomain(AbstractDomain):
    def __init__(self, checker: PathFeasibilityChecker):
        self._checker = checker

    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        if not isinstance(state1, PredicateAbstractState) or not isinstance(
            state2, PredicateAbstractState
        ):
            return False
        return all(
            self._checker.implies(state1.predicates, predicate)
            for predicate in state2.predicates
        )

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        if not isinstance(state1, PredicateAbstractState) or not isinstance(
            state2, PredicateAbstractState
        ):
            return self.get_top()
        common: list[LinearConstraint] = []
        for predicate in state1.predicates:
            if self._checker.implies(state2.predicates, predicate):
                common.append(predicate)
        for predicate in state2.predicates:
            if self._checker.implies(state1.predicates, predicate) and predicate not in common:
                common.append(predicate)
        return PredicateAbstractState.from_constraints(common)

    def get_top(self) -> AbstractState:
        return PredicateAbstractState()

    def get_bottom(self) -> AbstractState:
        return PredicateAbstractState(
            (LinearConstraint(LinearExpr.constant(1), "=="),)
        )


class PredicateTransferRelation(TransferRelation):
    def __init__(self, checker: PathFeasibilityChecker):
        self._checker = checker

    def get_abstract_successors(
        self, state: AbstractState, precision: Precision, edge: CFAEdge
    ) -> list[AbstractState]:
        if not isinstance(state, PredicateAbstractState):
            return []

        if edge.edge_type == EdgeType.ASSIGNMENT:
            transformed = self._apply_assignment(
                state.predicates, edge.variable, edge.expression
            )
            return [PredicateAbstractState.from_constraints(transformed)]

        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            truth_value = edge.edge_type == EdgeType.ASSUME_TRUE
            new_predicates = parse_condition_constraints(edge.expression, truth_value)
            if new_predicates is None:
                return [state]
            combined = [*state.predicates, *new_predicates]
            if not self._checker.is_satisfiable(combined):
                return []
            return [PredicateAbstractState.from_constraints(combined)]

        return [state]

    def _apply_assignment(
        self,
        predicates: tuple[LinearConstraint, ...],
        variable: str,
        expression: str,
    ) -> list[LinearConstraint]:
        if is_nondeterministic(expression):
            return [predicate for predicate in predicates if not predicate.contains(variable)]

        rhs = parse_linear_expression(expression)
        if rhs is None:
            return [predicate for predicate in predicates if not predicate.contains(variable)]

        coeff = rhs.coefficient(variable)
        rest = rhs.without_variable(variable)
        transformed: list[LinearConstraint]

        if coeff == 1:
            old_value = LinearExpr.variable(variable) - rest
            transformed = [predicate.substitute(variable, old_value) for predicate in predicates]
        elif coeff == -1:
            old_value = rest - LinearExpr.variable(variable)
            transformed = [predicate.substitute(variable, old_value) for predicate in predicates]
        else:
            transformed = [predicate for predicate in predicates if not predicate.contains(variable)]

        if coeff == 0:
            transformed.append(LinearConstraint(LinearExpr.variable(variable) - rhs, "=="))

        return transformed


class PredicateCPA(ConfigurableProgramAnalysis):
    def __init__(self):
        self._checker = PathFeasibilityChecker()
        self._domain = PredicateAbstractDomain(self._checker)
        self._transfer = PredicateTransferRelation(self._checker)
        self._merge = SeparateMergeOperator()
        self._stop = DomainStopOperator(self._domain)
        self._precision = TrivialPrecision()

    @property
    def checker(self) -> PathFeasibilityChecker:
        return self._checker

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return PredicateAbstractState()

    def get_initial_precision(self) -> Precision:
        return self._precision


def run_predicate_analysis(cfa: CFA, timelimit: int) -> VerificationResult:
    cpa = CompositeCPA((LocationCPA(), PredicateCPA()))
    return run_cpa_algorithm(cfa, cpa, timelimit)


__all__ = [
    "LinearConstraint",
    "LinearExpr",
    "PathFeasibilityChecker",
    "PredicateAbstractState",
    "PredicateCPA",
    "parse_condition_constraints",
    "parse_linear_expression",
    "run_predicate_analysis",
]

