"""Simplified k-induction using bounded symbolic exploration and parity invariants."""

from __future__ import annotations

import ast
from collections import deque
from dataclasses import dataclass
import re
import time
from typing import Iterable

from cpachecker.cfa import CFA, CFAEdge, EdgeType
from cpachecker.cpa_interface import (
    AbstractDomain,
    AbstractState,
    ConfigurableProgramAnalysis,
    MergeOperator,
    Precision,
    StopOperator,
    TransferRelation,
)
from cpachecker.expression import is_nondeterministic
from cpachecker.result import VerificationResult, Verdict
from cpachecker.analyses.bmc import detect_back_edges
from cpachecker.analyses.predicate_analysis import (
    LinearConstraint,
    LinearExpr,
    PathFeasibilityChecker,
    PredicateTransferRelation,
    parse_condition_constraints,
    parse_linear_expression,
)
from cpachecker.analyses.value_analysis import (
    CompositeCPA,
    DomainStopOperator,
    LocationCPA,
    SeparateMergeOperator,
    TrivialPrecision,
    run_cpa_algorithm,
)


MAX_K = 100
INTEGER_SUFFIX_RE = re.compile(r"\b(\d+)[UuLl]+\b")


def _sanitize_expression(expression: str) -> str:
    return INTEGER_SUFFIX_RE.sub(r"\1", expression.strip())


def _evaluate_parity(
    expr: LinearExpr | None, parity_map: dict[str, int | None]
) -> int | None:
    if expr is None:
        return None

    parity = expr.const % 2
    for variable, coeff in expr.coeffs:
        if coeff % 2 == 0:
            continue
        value = parity_map.get(variable)
        if value is None:
            return None
        parity = (parity + value) % 2
    return parity


def _parse_mod2_assumption(
    expression: str, truth_value: bool
) -> tuple[LinearExpr, int] | None:
    try:
        tree = ast.parse(_sanitize_expression(expression), mode="eval")
    except SyntaxError:
        return None

    node = tree.body
    if not isinstance(node, ast.Compare) or len(node.ops) != 1 or len(node.comparators) != 1:
        return None

    mod_expr: LinearExpr | None = None
    comparison_value: int | None = None

    if (
        isinstance(node.left, ast.BinOp)
        and isinstance(node.left.op, ast.Mod)
        and isinstance(node.left.right, ast.Constant)
        and int(node.left.right.value) == 2
    ):
        mod_expr = _parse_parity_linear(node.left.left)
        comparator = node.comparators[0]
        if isinstance(comparator, ast.Constant):
            comparison_value = int(comparator.value) % 2
    elif (
        isinstance(node.comparators[0], ast.BinOp)
        and isinstance(node.comparators[0].op, ast.Mod)
        and isinstance(node.comparators[0].right, ast.Constant)
        and int(node.comparators[0].right.value) == 2
    ):
        mod_expr = _parse_parity_linear(node.comparators[0].left)
        if isinstance(node.left, ast.Constant):
            comparison_value = int(node.left.value) % 2

    if mod_expr is None or comparison_value is None:
        return None

    operator_node = node.ops[0]
    if isinstance(operator_node, ast.Eq):
        required = comparison_value if truth_value else (comparison_value + 1) % 2
    elif isinstance(operator_node, ast.NotEq):
        required = (comparison_value + 1) % 2 if truth_value else comparison_value
    else:
        return None

    return mod_expr, required


def _parse_parity_linear(node: ast.AST) -> LinearExpr | None:
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, bool)):
        return LinearExpr.constant(int(node.value))
    if isinstance(node, ast.Name):
        return LinearExpr.variable(node.id)
    if isinstance(node, ast.UnaryOp):
        operand = _parse_parity_linear(node.operand)
        if operand is None:
            return None
        if isinstance(node.op, ast.USub):
            return operand.scale(-1)
        if isinstance(node.op, ast.UAdd):
            return operand
        return None
    if isinstance(node, ast.BinOp):
        left = _parse_parity_linear(node.left)
        right = _parse_parity_linear(node.right)
        if left is None or right is None:
            return None
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            left_const = left.evaluate_constant()
            right_const = right.evaluate_constant()
            if left_const is not None:
                return right.scale(left_const)
            if right_const is not None:
                return left.scale(right_const)
            return None
    return None


def _update_parity_from_mod_assumption(
    parity_map: dict[str, int | None],
    mod_expr: LinearExpr,
    required_parity: int,
) -> dict[str, int | None] | None:
    current_value = _evaluate_parity(mod_expr, parity_map)
    if current_value is not None:
        if current_value != required_parity:
            return None
        return dict(parity_map)

    odd_terms = [(variable, coeff) for variable, coeff in mod_expr.coeffs if coeff % 2]
    if len(odd_terms) != 1:
        return dict(parity_map)

    variable, _ = odd_terms[0]
    known_contrib = mod_expr.const % 2
    for other_variable, coeff in odd_terms:
        if other_variable == variable:
            continue
        other_value = parity_map.get(other_variable)
        if other_value is None:
            return dict(parity_map)
        known_contrib = (known_contrib + coeff * other_value) % 2

    updated = dict(parity_map)
    updated[variable] = (required_parity - known_contrib) % 2
    return updated


@dataclass(frozen=True)
class SymbolicExecutionState:
    location: int
    predicates: tuple[LinearConstraint, ...] = ()
    parity: tuple[tuple[str, int], ...] = ()
    backedge_counts: tuple[tuple[tuple[int, int], int], ...] = ()

    def parity_map(self) -> dict[str, int | None]:
        return {variable: value for variable, value in self.parity}

    def with_state(
        self,
        location: int,
        predicates: Iterable[LinearConstraint],
        parity: dict[str, int | None],
    ) -> "SymbolicExecutionState":
        normalized_predicates = tuple(
            sorted({predicate.normalize() for predicate in predicates}, key=lambda item: repr(item))
        )
        normalized_parity = tuple(
            sorted((variable, value) for variable, value in parity.items() if value is not None)
        )
        return SymbolicExecutionState(
            location=location,
            predicates=normalized_predicates,
            parity=normalized_parity,
            backedge_counts=self.backedge_counts,
        )

    def count_for(self, edge_key: tuple[int, int]) -> int:
        return dict(self.backedge_counts).get(edge_key, 0)

    def increment_backedge(self, edge_key: tuple[int, int]) -> "SymbolicExecutionState":
        counts = dict(self.backedge_counts)
        counts[edge_key] = counts.get(edge_key, 0) + 1
        return SymbolicExecutionState(
            self.location,
            self.predicates,
            self.parity,
            tuple(sorted(counts.items())),
        )


@dataclass
class _BaseCaseResult:
    verdict: Verdict | None
    truncated: bool
    explored_states: int
    witness: list[dict]


class _SymbolicTransfer:
    def __init__(self):
        self.checker = PathFeasibilityChecker()
        self._predicate_transfer = PredicateTransferRelation(self.checker)

    def take_edge(
        self, state: SymbolicExecutionState, edge: CFAEdge
    ) -> SymbolicExecutionState | None:
        parity = state.parity_map()
        predicates = list(state.predicates)

        if edge.edge_type == EdgeType.ASSIGNMENT:
            predicates = self._predicate_transfer._apply_assignment(
                state.predicates, edge.variable, edge.expression
            )
            if is_nondeterministic(edge.expression):
                parity.pop(edge.variable, None)
            else:
                expr = parse_linear_expression(edge.expression)
                value = _evaluate_parity(expr, parity)
                if value is None:
                    parity.pop(edge.variable, None)
                else:
                    parity[edge.variable] = value
            return state.with_state(edge.target, predicates, parity)

        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            truth_value = edge.edge_type == EdgeType.ASSUME_TRUE
            mod_assumption = _parse_mod2_assumption(edge.expression, truth_value)
            if mod_assumption is not None:
                mod_expr, required = mod_assumption
                updated_parity = _update_parity_from_mod_assumption(
                    parity, mod_expr, required
                )
                if updated_parity is None:
                    return None
                return state.with_state(edge.target, predicates, updated_parity)

            new_predicates = parse_condition_constraints(edge.expression, truth_value)
            if new_predicates is None:
                return state.with_state(edge.target, predicates, parity)
            predicates.extend(new_predicates)
            if not self.checker.is_satisfiable(predicates):
                return None
            return state.with_state(edge.target, predicates, parity)

        return state.with_state(edge.target, predicates, parity)


def _evaluate_constraint(
    constraint: LinearConstraint, assignment: dict[str, int]
) -> bool:
    value = constraint.expr.const
    for variable, coeff in constraint.expr.coeffs:
        value += coeff * assignment[variable]
    if constraint.operator == "==":
        return value == 0
    if constraint.operator == "!=":
        return value != 0
    if constraint.operator == "<":
        return value < 0
    if constraint.operator == "<=":
        return value <= 0
    if constraint.operator == ">":
        return value > 0
    if constraint.operator == ">=":
        return value >= 0
    raise ValueError(f"Unsupported operator: {constraint.operator}")


def _find_model(
    variables: list[str],
    predicates: tuple[LinearConstraint, ...],
    parity: dict[str, int | None],
    search_min: int = -2,
    search_max: int = 20,
) -> dict[str, int] | None:
    ordered = sorted(
        {variable for variable in variables}
        | {variable for predicate in predicates for variable in predicate.expr.variables()}
        | set(parity)
    )

    if not ordered:
        return {}

    def search(index: int, current: dict[str, int]) -> dict[str, int] | None:
        if index == len(ordered):
            if all(_evaluate_constraint(predicate, current) for predicate in predicates):
                return dict(current)
            return None

        variable = ordered[index]
        parity_value = parity.get(variable)
        for candidate in range(search_min, search_max + 1):
            if parity_value is not None and candidate % 2 != parity_value:
                continue
            current[variable] = candidate
            result = search(index + 1, current)
            if result is not None:
                return result
        current.pop(variable, None)
        return None

    return search(0, {})


def _render_symbolic_witness(
    cfa: CFA, path: list[tuple[CFAEdge | None, SymbolicExecutionState]]
) -> list[dict]:
    rendered: list[dict] = []
    for edge, state in path:
        model = _find_model(cfa.variables, state.predicates, state.parity_map())
        step = {
            "location": state.location,
            "values": model or {},
            "parity": {variable: value for variable, value in state.parity},
            "predicates": [repr(predicate) for predicate in state.predicates],
        }
        if edge is not None:
            step["edge_type"] = edge.edge_type.value
            if edge.variable:
                step["variable"] = edge.variable
            if edge.expression:
                step["expression"] = edge.expression
        rendered.append(step)
    return rendered


def _run_symbolic_base_case(
    cfa: CFA,
    bound: int,
    deadline: float,
    back_edges: set[tuple[int, int]],
) -> _BaseCaseResult:
    transfer = _SymbolicTransfer()
    initial = SymbolicExecutionState(cfa.entry_node)
    frontier: deque[tuple[SymbolicExecutionState, list[tuple[CFAEdge | None, SymbolicExecutionState]]]] = deque(
        [(initial, [(None, initial)])]
    )
    reached: set[SymbolicExecutionState] = {initial}
    truncated = False
    explored_states = 0

    while frontier:
        if time.monotonic() > deadline:
            return _BaseCaseResult(Verdict.UNKNOWN, truncated, explored_states, [])

        state, path = frontier.popleft()
        explored_states += 1

        if cfa.nodes[state.location].is_error:
            return _BaseCaseResult(
                Verdict.FALSE,
                truncated,
                explored_states,
                _render_symbolic_witness(cfa, path),
            )

        for edge in cfa.get_successors(state.location):
            edge_key = (edge.source, edge.target)
            if edge_key in back_edges and state.count_for(edge_key) >= bound:
                truncated = True
                continue

            successor = transfer.take_edge(state, edge)
            if successor is None:
                continue

            if edge_key in back_edges:
                successor = successor.increment_backedge(edge_key)

            next_path = [*path, (edge, successor)]
            if cfa.nodes[successor.location].is_error:
                return _BaseCaseResult(
                    Verdict.FALSE,
                    truncated,
                    explored_states,
                    _render_symbolic_witness(cfa, next_path),
                )

            if successor not in reached:
                reached.add(successor)
                frontier.append((successor, next_path))

    verdict = Verdict.TRUE if not truncated else None
    return _BaseCaseResult(verdict, truncated, explored_states, [])


@dataclass(frozen=True)
class ParityAbstractState(AbstractState):
    values: tuple[tuple[str, int], ...] = ()

    @classmethod
    def from_map(cls, values: dict[str, int | None]) -> "ParityAbstractState":
        filtered = tuple(sorted((variable, value) for variable, value in values.items() if value is not None))
        return cls(filtered)

    def __eq__(self, other) -> bool:
        return isinstance(other, ParityAbstractState) and self.values == other.values

    def __hash__(self) -> int:
        return hash(self.values)

    def __repr__(self) -> str:
        readable = {variable: "even" if value == 0 else "odd" for variable, value in self.values}
        return f"ParityAbstractState({readable!r})"

    def as_map(self) -> dict[str, int | None]:
        return {variable: value for variable, value in self.values}


class ParityAbstractDomain(AbstractDomain):
    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        if not isinstance(state1, ParityAbstractState) or not isinstance(
            state2, ParityAbstractState
        ):
            return False
        values1 = state1.as_map()
        for variable, value in state2.values:
            if values1.get(variable) != value:
                return False
        return True

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        if not isinstance(state1, ParityAbstractState) or not isinstance(
            state2, ParityAbstractState
        ):
            return self.get_top()
        values1 = state1.as_map()
        joined: dict[str, int] = {}
        for variable, value in state2.values:
            if values1.get(variable) == value:
                joined[variable] = value
        return ParityAbstractState.from_map(joined)

    def get_top(self) -> AbstractState:
        return ParityAbstractState()

    def get_bottom(self) -> AbstractState:
        return ParityAbstractState((("__bottom__", 0),))


class ParityTransferRelation(TransferRelation):
    def get_abstract_successors(
        self, state: AbstractState, precision: Precision, edge: CFAEdge
    ) -> list[AbstractState]:
        if not isinstance(state, ParityAbstractState):
            return []

        parity = state.as_map()

        if edge.edge_type == EdgeType.ASSIGNMENT:
            if is_nondeterministic(edge.expression):
                parity.pop(edge.variable, None)
                return [ParityAbstractState.from_map(parity)]
            expr = parse_linear_expression(edge.expression)
            value = _evaluate_parity(expr, parity)
            if value is None:
                parity.pop(edge.variable, None)
            else:
                parity[edge.variable] = value
            return [ParityAbstractState.from_map(parity)]

        if edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            truth_value = edge.edge_type == EdgeType.ASSUME_TRUE
            mod_assumption = _parse_mod2_assumption(edge.expression, truth_value)
            if mod_assumption is None:
                return [state]
            expr, required = mod_assumption
            updated = _update_parity_from_mod_assumption(parity, expr, required)
            if updated is None:
                return []
            return [ParityAbstractState.from_map(updated)]

        return [state]


class ParityCPA(ConfigurableProgramAnalysis):
    def __init__(self):
        self._domain = ParityAbstractDomain()
        self._transfer = ParityTransferRelation()
        self._merge = SeparateMergeOperator()
        self._stop = DomainStopOperator(self._domain)
        self._precision = TrivialPrecision()

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        return ParityAbstractState()

    def get_initial_precision(self) -> Precision:
        return self._precision


def run_k_induction(cfa: CFA, timelimit: int) -> VerificationResult:
    deadline = time.monotonic() + timelimit
    back_edges = detect_back_edges(cfa)
    total_explored_states = 0

    for k in range(1, MAX_K + 1):
        base_case = _run_symbolic_base_case(cfa, k, deadline, back_edges)
        total_explored_states += base_case.explored_states

        if base_case.verdict == Verdict.UNKNOWN:
            return VerificationResult(
                verdict=Verdict.UNKNOWN,
                statistics={
                    "algorithm": "k-induction",
                    "phase": "base",
                    "k": k,
                    "explored_states": total_explored_states,
                    "back_edges": sorted(back_edges),
                },
            )

        if base_case.verdict == Verdict.FALSE:
            return VerificationResult(
                verdict=Verdict.FALSE,
                property_violated="assertion",
                error_path=base_case.witness,
                statistics={
                    "algorithm": "k-induction",
                    "phase": "base",
                    "k": k,
                    "explored_states": total_explored_states,
                    "back_edges": sorted(back_edges),
                    "counterexample": base_case.witness,
                },
            )

        if time.monotonic() > deadline:
            return VerificationResult(
                verdict=Verdict.UNKNOWN,
                statistics={
                    "algorithm": "k-induction",
                    "phase": "inductive",
                    "k": k,
                    "explored_states": total_explored_states,
                    "back_edges": sorted(back_edges),
                },
            )

        remaining = max(1, int(deadline - time.monotonic()))
        inductive = run_cpa_algorithm(
            cfa, CompositeCPA((LocationCPA(), ParityCPA())), remaining
        )
        if inductive.verdict == Verdict.TRUE:
            return VerificationResult(
                verdict=Verdict.TRUE,
                statistics={
                    "algorithm": "k-induction",
                    "phase": "inductive",
                    "k": k,
                    "explored_states": total_explored_states,
                    "back_edges": sorted(back_edges),
                },
            )

    return VerificationResult(
        verdict=Verdict.UNKNOWN,
        statistics={
            "algorithm": "k-induction",
            "phase": "inductive",
            "k": MAX_K,
            "explored_states": total_explored_states,
            "back_edges": sorted(back_edges),
        },
    )


__all__ = ["ParityCPA", "run_k_induction"]
